/**
 * Prepares file attachments for the WaSOS JSON endpoint.                                                                                                                                        
 *              
 * Reads pre-downloaded buffers from global context (stored by                                                                                                                                   
 * Fetch Rayvn files) and converts them to NewFileRequest objects
 * on msg.payload.files for the standard JSON POST.                                                                                                                                              
 *              
 * When no buffers are available, msg.payload.files stays empty
 * and the message is sent as text-only.                                                                                                                                                         
 *
 * Failures are appended to metadata.files.failed.                                                                                                                                               
 */
const utils = global.get("utils");
const items = msg.metadata.files.items;

const loaded = [];
const failed = [];

for (const file of items) {
    const buffer = global.get("files." + file.context_key);
    if (!buffer || buffer.length === 0) {
        node.error("No buffer for: " + file.context_key);
        failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }

    const name = file.name || "file.bin";
    const ext = name.includes(".") ? name.split(".").pop() : "";

    loaded.push({
        filename: name,
        extension: ext,
        filetype: file.type || "application/octet-stream",
        blob: Array.from(buffer)
    });

    node.log("Prepared for WaSOS: " + name + " (" + buffer.length + " bytes, " + file.type + ")");
}

if (failed.length > 0) {
    msg.metadata.files.failed = [...msg.metadata.files.failed, ...failed];
}

const all_failed = msg.metadata.files.failed;
if (all_failed.length > 0) {
    const total = loaded.length + all_failed.length;
    const notice = "\n\n[" + all_failed.length + "/" + total
        + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";
    msg.payload.content = (msg.payload.content || "") + notice;
}

msg.payload.files = loaded;

return msg;
